public class StringComparisonDemo {
    public static void main(String[] args) {
        // Literals use the same pooled object
        String literal1 = "admin";
        String literal2 = "admin";
        System.out.println(literal1 == literal2);        // true (same object)
        System.out.println(literal1.equals(literal2));   // true (same content)

        // Runtime strings create new objects
        String runtime = new String("admin");
        System.out.println(literal1 == runtime);         // false (different objects)
        System.out.println(literal1.equals(runtime));    // true (same content)

        // User input creates new objects
        var userInput = readUserInput();  // returns "admin"
        System.out.println("admin" == userInput);        // false (different objects)
        System.out.println("admin".equals(userInput));   // true (same content)
    }

    static String readUserInput() {
        return new String("admin");  // simulates reading from external source
    }
}

import java.util.*;

public class StringOrderingDemo {
    public static void main(String[] args) {
        // Basic compareTo() usage
        String first = "apple";
        String second = "banana";
        int result = first.compareTo(second);
        System.out.println(result < 0 ? "apple comes first" : "banana comes first");

        // Sorting a list of usernames
        var usernames = new ArrayList<>(List.of("charlie", "alice", "bob"));
        Collections.sort(usernames);  // uses compareTo() internally
        System.out.println(usernames);  // [alice, bob, charlie]

        // TreeSet automatically sorts using compareTo()
        var orderedNames = new TreeSet<String>();
        orderedNames.add("zebra");
        orderedNames.add("apple");
        orderedNames.add("mango");
        System.out.println(orderedNames);  // [apple, mango, zebra]

        // Case sensitivity demonstration
        System.out.println("Apple".compareTo("apple"));  // negative (uppercase first)
        System.out.println("apple".compareToIgnoreCase("Apple"));  // 0 (ignores case)
    }
}

public class StringSearchDemo {
    public static void main(String[] args) {
        var email = "user@company.com";
        var logMessage = "ERROR: Database connection failed";
        var filename = "report_2024.pdf";

        // contains() - check if substring exists anywhere
        if (email.contains("@")) {
            System.out.println("Valid email format");
        }

        // startsWith() - check prefix
        if (logMessage.startsWith("ERROR")) {
            System.out.println("Critical log entry found");
        }

        // endsWith() - check suffix
        if (filename.endsWith(".pdf")) {
            System.out.println("PDF document detected");
        }

        // indexOf() - find position of substring
        int atPosition = email.indexOf("@");
        if (atPosition != -1) {  // always check for -1
            String username = email.substring(0, atPosition);
            System.out.println("Username: " + username);  // "user"
        }

        // lastIndexOf() - find last occurrence
        var path = "/home/user/documents/file.txt";
        int lastSlash = path.lastIndexOf("/");
        String fileName = path.substring(lastSlash + 1);  // "file.txt"
        System.out.println(fileName);
    }
}

import java.util.*;

public class CaseInsensitiveDemo {
    public static void main(String[] args) {
        var userRole = "Admin";
        var expectedRole = "ADMIN";

        // Correct: equalsIgnoreCase() for equality
        if (userRole.equalsIgnoreCase(expectedRole)) {
            System.out.println("Access granted");
        }

        // Correct: compareToIgnoreCase() for ordering
        var names = new ArrayList<>(List.of("Alice", "bob", "CHARLIE"));
        names.sort((a, b) -> a.compareToIgnoreCase(b));
        System.out.println(names);  // [Alice, bob, CHARLIE] sorted ignoring case

        // Wrong: toLowerCase() breaks in Turkish locale
        Locale.setDefault(new Locale("tr", "TR"));
        String title = "TITLE";
        System.out.println(title.toLowerCase().equals("title"));  // false in Turkish!
        System.out.println(title.equalsIgnoreCase("title"));      // true (correct)

        // Using String.CASE_INSENSITIVE_ORDER comparator
        var tags = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
        tags.add("Java");
        tags.add("PYTHON");
        tags.add("python");  // duplicate, won't be added
        System.out.println(tags);  // [Java, PYTHON] case-insensitive deduplication
    }
}

import java.util.Objects;
import java.util.Optional;

public class NullSafeComparisonDemo {
    public static void main(String[] args) {
        String userInput = getUserInput();  // might return null
        String expectedRole = "admin";

        // Wrong: crashes if userInput is null
        // if (userInput.equals("admin")) { ... }  // NullPointerException!

        // Correct: literal-first pattern
        if ("admin".equals(userInput)) {
            System.out.println("Admin access granted");
        }

        // Correct: Objects.equals() for symmetric comparison
        if (Objects.equals(userInput, expectedRole)) {
            System.out.println("Roles match");
        }

        // Objects.equals() treats two nulls as equal
        String a = null;
        String b = null;
        System.out.println(Objects.equals(a, b));  // true
        System.out.println("admin".equals(a));     // false

        // Traditional null check (verbose but explicit)
        if (userInput != null && userInput.equals("admin")) {
            System.out.println("Explicit null safety");
        }

        // Using Optional for null-safe operations
        boolean isAdmin = Optional.ofNullable(userInput)
            .map(role -> role.equals("admin"))
            .orElse(false);
    }

    static String getUserInput() {
        return Math.random() > 0.5 ? "admin" : null;
    }
}
